function preRenderPlayerSprites() {
  const W = 80, H = 100;
  function makeFrame(pose) {
    const c = document.createElement('canvas');
    c.width = W; c.height = H;
    drawSpritePose(c.getContext('2d'), pose);
    return c;
  }
  const run = RUN_POSES.map(p => makeFrame(p));
  G.offscreen.player = {
    run,
    jump: JUMP_POSES.map(p => makeFrame(p)),
    slide: SLIDE_POSES.map(p => makeFrame(p)),
    hit: makeFrame(HIT_POSE),
    lookback: makeFrame(LOOKBACK_POSE),
    kick: makeFrame(KICK_POSE),
  };
}

