file.content:
if (!sprites) return;
ctx.save();
ctx.translate(p.x, p.y);

/* 无敌闪烁 */
let alpha = 1;
if (G.invincible > 0 && Math.floor(G.invincible / 4) % 2 === 0) {
  alpha = 0.35;
}

/* 阴影 */
const sliding = p.state === STATE_SLIDE;
ctx.fillStyle = sliding ? 'rgba(0,0,0,0.35)' : 'rgba(0,0,0,0.25)';
ctx.beginPath();
if (sliding) {
  /* 横向滑动——宽扁椭圆 */
  ctx.ellipse(-22, 6, 35, 5, 0, 0, Math.PI * 2);
} else {
  ctx.ellipse(0, 12, 20, 7, 0, 0, Math.PI * 2);
}
ctx.fill();

/* 选择精灵帧 */
let frame = sprites.run[0]; // 默认第一帧
const SW = 80, SH = 100;

if (p.state === STATE_RUN) {
  /* 庆祝动画 */
  if (p.celebrateTimer > 0 && p.celebrateType) {
    if (p.celebrateType === 'lookback') {
      frame = sprites.lookback;
    } else if (p.celebrateType === 'kick') {
      frame = p.celebrateTimer > 15 ? sprites.kick : sprites.run[Math.floor(G.frameCount / 8) % 8];
    }
  } else {
    /* 8帧跑步循环 ~7.5fps */
    frame = sprites.run[Math.floor(G.frameCount / 8) % 8];
  }
} else if (p.state === STATE_JUMP) {
  /* 4阶段跳跃动画：预蹲(0.25s)→腾空(1.0s)→下落(0.7s)→落地(0.55s) */
  const t = p.stateTimer;
  if (t > 135)        frame = sprites.jump[0];  // 预蹲蓄力
  else if (t > 75)    frame = sprites.jump[1];  // 腾空上升
  else if (t > 33)    frame = sprites.jump[2];  // 下落
  else                frame = sprites.jump[3];  // 落地缓冲
} else if (p.state === STATE_SLIDE) {
  /* 5阶段滑铲：进入→过渡→贴地1→贴地2→起身（-90°旋转绘制） */
  const t = p.stateTimer;
  if (t > 85)         frame = sprites.slide[0]; // 进入
  else if (t > 65)    frame = sprites.slide[1]; // 过渡
  else if (t > 45)    frame = sprites.slide[2]; // 贴地1
  else if (t > 25)    frame = sprites.slide[3]; // 贴地2
  else                frame = sprites.slide[4]; // 起身
} else if (p.state === STATE_HIT) {
  frame = sprites.hit;
}

/* 绘制精灵（居中，底部对齐到地面） */
if (alpha < 1) ctx.globalAlpha = alpha;

