const HIT_STUN = 18;                // 受伤后仰帧数
const CELEBRATE_LOOKBACK = 40;      // 回头庆祝帧数
const CELEBRATE_KICK = 35;          // 踢腿庆祝帧数

/* 生成时机 */
const COIN_SPAWN_BASE = 150;        // 金币基础生成间隔（帧）
const COIN_SPAWN_RAND = 120;        // 金币随机间隔加成
const POWERUP_SPAWN_BASE = 300;     // 道具基础生成间隔（帧）
const POWERUP_SPAWN_RAND = 400;     // 道具随机间隔加成
const MAX_POWERUPS = 2;             // 同时存在道具上限
const OBSTACLE_SPACING_NEAR = 100;  // 障碍物最小间距（近端）
const OBSTACLE_SPACING_FAR = 30;    // 障碍物最小间距（远端）

/* 磁铁效果 */
const MAGNET_DIST_NEAR = 80;        // 磁铁吸引近端距离
const MAGNET_DIST_FAR = -20;        // 磁铁吸引远端距离
const MAGNET_PULL = 0.08;           // 磁铁拉扯力度
const MAGNET_SPEED_BOOST = 0.3;     // 磁铁加速系数

/* 视觉效果 */
const SHAKE_DURATION = 12;          // 受伤震动帧数
const SHAKE_INTENSITY_X = 6;        // X轴震动强度
const SHAKE_INTENSITY_Y = 4;        // Y轴震动强度
const FLASH_ALPHA_MAX = 0.25;       // 受伤红屏峰值透明度
const FLASH_FADE = 0.02;            // 红屏每帧衰减
const SPEED_LINE_THRESHOLD = 0.3;   // 速度线出现阈值（速度比）
const SPEED_LINE_COUNT = 12;        // 速度线条数
const SPEED_LINE_INTENSITY = 0.5;   // 速度线强度系数
const PARALLAX_FAR = 0.15;          // 远景视差滚动速度
const PARALLAX_NEAR = 0.3;          // 近景视差滚动速度

/* 动画 */
const ANIM_INTERVAL = 8;            // 动画帧间隔（帧）
const DUST_INTERVAL = 4;            // 奔跑扬尘间隔（帧）

/* =========================== 工具函数 =========================== */
function lerp(a, b, t) { return a + (b - a) * t; }
function clamp(v, lo, hi) { return v < lo ? lo : v > hi ? hi : v; }
function randInt(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min; }
function randChoice(arr) { return arr[Math.floor(Math.random() * arr.length)]; }

/* =========================== Web Audio 音效系统 =========================== */
/** 初始化 AudioContext（需在首次用户交互后调用） */
function initAudio() {
  if (G.audioReady) return;
  try {
    G.audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    G.audioReady = true;
  } catch(e) {
    G.audioReady = false;
  }
}

/** 播放一个简单的合成音效 */
function playSound(freq, type, duration, vol, options) {
  if (!G.audioReady) return;
  const ctx = G.audioCtx;
  const opts = options || {};
  const now = ctx.currentTime;

  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = type || 'sine';
  osc.frequency.setValueAtTime(freq, now);
  if (opts.freqEnd) osc.frequency.linearRampToValueAtTime(opts.freqEnd, now + duration);
  gain.gain.setValueAtTime(vol || 0.15, now);
  gain.gain.exponentialRampToValueAtTime(0.001, now + duration);
  osc.connect(gain);
  gain.connect(ctx.destination);
  osc.start(now);

