  if (G.spawnTimer >= interval) {
    G.spawnTimer = 0;
    spawnObstacle();
  }
  G.coinTimer++;
  if (G.coinTimer > COIN_SPAWN_BASE + Math.random() * COIN_SPAWN_RAND) {
    G.coinTimer = 0;
    spawnCoinRow();
  }
  if (!G.powerupSpawnTimer) G.powerupSpawnTimer = POWERUP_SPAWN_BASE + Math.random() * POWERUP_SPAWN_RAND;
  G.powerupSpawnTimer--;
  if (G.powerupSpawnTimer <= 0) {
    G.powerupSpawnTimer = POWERUP_SPAWN_BASE + Math.random() * POWERUP_SPAWN_RAND;
