function updatePowerups(p) {
  for (let i = 0; i < G.powerups.length; i++) {
    const pu = G.powerups[i];
    if (!pu.active) continue;
    pu.dist -= G.speed;
    if (pu.dist < -400) { pu.active = false; continue; }
    pu.floatPhase += 0.05;
    if (!pu.collected && pu.dist < COLLECT_NEAR && pu.dist > COLLECT_FAR && Math.abs(pu.lane - p.lane) < COLLECT_LANE_RANGE) {
      pu.collected = true;
      pu.sparkTimer = 12;
      sfxPowerup();
      applyPowerup(p, pu.type);
      const s = worldToScreen(pu.dist);
      const sx = laneX(pu.lane, pu.dist);
      const puColor = pu.type === PUP_MAGNET ? '#ff44ff' : pu.type === PUP_SHIELD ? '#44aaff' : '#ffdd00';
      burstParticles(sx, s.y, 10, 30, 30, 6, [15, 35], [puColor, '#fff', puColor]);
    }
  }
  if (p.powerupTimer > 0) {
    p.powerupTimer--;
    if (p.powerupTimer <= 0) {
      p.activePowerup = null;
      p.scoreMultiplier = 1;
    }
  }
  if (p.activePowerup === PUP_MAGNET) {
    for (let i = 0; i < G.coins.length; i++) {
      const c = G.coins[i];
      if (!c.active || c.collected) continue;
      if (Math.abs(c.lane - p.lane) < MAGNET_RANGE && c.dist < MAGNET_DIST_NEAR && c.dist > MAGNET_DIST_FAR) {
        c.lane += (p.lane - c.lane) * MAGNET_PULL;
        c.dist -= G.speed * MAGNET_SPEED_BOOST;
      }
    }
  }
}

function updateFinalize(p) {
