    /* 跳跃弧线：先升后降，stateTimer 越小越接近落地 */
    const progress = 1 - p.stateTimer / JUMP_DURATION; // 0=起跳, 1=落地
    const arc = Math.sin(progress * Math.PI);          // 0→1→0 抛物线
    p.y = G.groundY - arc * JUMP_PEAK_HEIGHT;
  } else if (p.state === STATE_SLIDE) {
    /* 滑铲：旋转90°后角色水平贴地，脚部对齐地面 */
    p.y = G.groundY;
