/* =========================== 绘制火车 =========================== */
function drawTrain(ctx, t, lane, dist, baseSx, baseSy, baseScale) {
  const sc = Math.max(0.15, baseScale);
  const carLen = TRAIN_CAR_LENGTH * sc * 0.18; // 透视缩放

  for (let car = 0; car < t.carCount; car++) {
    const carDist = dist - car * TRAIN_CAR_LENGTH;
    if (carDist < -100 || carDist > G.maxDist + 200) continue;

    const s = worldToScreen(carDist);
    const sx = laneX(t.lane, carDist);
    const carH = TRAIN_CAR_HEIGHT * s.scale;
    const carW = carLen * 1.1;

    /* 车身 */
    const bodyColor = car % 2 === 0 ? '#3a5070' : '#4a6078';
    ctx.fillStyle = bodyColor;
    ctx.fillRect(sx - carW/2, s.y - carH, carW, carH);

    /* 车厢顶部 */
    ctx.fillStyle = '#5a7088';
    ctx.fillRect(sx - carW/2 + 2*s.scale, s.y - carH, carW - 4*s.scale, 5*s.scale);

    /* 窗户 */
    const winCount = 3;
    const winW = carW * 0.18;
    const winH = carH * 0.28;
    const winY = s.y - carH * 0.75;
    for (let w = 0; w < winCount; w++) {
      const wx = sx - carW/2 + carW * (0.15 + w * 0.28);
      ctx.fillStyle = '#aaccff';
      ctx.fillRect(wx, winY, winW, winH);
      ctx.fillStyle = 'rgba(255,255,200,0.5)';
      ctx.fillRect(wx + winW*0.2, winY, winW*0.6, winH);
    }

    /* 底盘 */
    ctx.fillStyle = '#222';
    ctx.fillRect(sx - carW/2 - 2*s.scale, s.y - 2*s.scale, carW + 4*s.scale, 4*s.scale);

    /* 车轮 */
    ctx.fillStyle = '#111';
    const wheelR = 4 * s.scale;
    for (let wh = 0; wh < 2; wh++) {
      const wx = sx - carW * 0.28 + wh * carW * 0.56;
      ctx.beginPath();
      ctx.arc(wx, s.y + 1*s.scale, wheelR, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#333';
      ctx.lineWidth = 0.5;
      ctx.stroke();
    }

    /* 车厢间连接 */
    if (car < t.carCount - 1) {
      ctx.strokeStyle = '#333';
      ctx.lineWidth = 1.5 * s.scale;
      ctx.beginPath();
      ctx.moveTo(sx - carW/2, s.y - carH * 0.3);
      const nextS = worldToScreen(carDist - TRAIN_CAR_LENGTH);
      const nextSx = laneX(t.lane, carDist - TRAIN_CAR_LENGTH);
      ctx.lineTo(nextSx + carLen/2, nextS.y - carH * 0.3);
      ctx.stroke();
    }
  }
}

