function updateTrains(p) {
  for (let i = 0; i < G.trains.length; i++) {
    const t = G.trains[i];
    if (!t.active) continue;
    /* 火车以略快于玩家的速度前进（追赶玩家） */
    t.dist -= G.speed * TRAIN_SPEED_FACTOR;
    if (t.dist < -TRAIN_CAR_COUNT_MAX * TRAIN_CAR_LENGTH - 200) {
      t.active = false; continue;
    }
    /* 每节车厢碰撞检测 */
    for (let car = 0; car < t.carCount; car++) {
      const carDist = t.dist - car * TRAIN_CAR_LENGTH;
      if (carDist < COLLISION_NEAR && carDist > COLLISION_FAR && Math.abs(t.lane - p.lane) < SAME_LANE_THRESHOLD) {
        if (G.invincible <= 0) {
          hurtPlayer(1);
          break;
        }
      }
    }
    /* 通过检测（最后一节车厢通过后触发庆祝） */
    if (!t.passed) {
      const lastCarDist = t.dist - (t.carCount - 1) * TRAIN_CAR_LENGTH;
      if (lastCarDist < COLLISION_FAR && Math.abs(t.lane - p.lane) < SAME_LANE_THRESHOLD) {
        t.passed = true;
        addCombo('dodge');
      }
    }
  }
}

function updateObstacles(p) {
  for (let i = 0; i < G.obstacles.length; i++) {
    const obs = G.obstacles[i];
    if (!obs.active) continue;
    obs.dist -= G.speed;
    if (obs.dist < -400) { obs.active = false; continue; }
    if (!obs.passed && obs.dist < COLLISION_NEAR && obs.dist > COLLISION_FAR) {
      if (sameLane(obs)) {
        if (obs.type === OBS_LOW && p.state === STATE_SLIDE) continue;
        if (obs.type === OBS_MID && p.state === STATE_JUMP) continue;
        hurtPlayer(1);
      }
    }
    if (!obs.passed && obs.dist < COLLISION_FAR && sameLane(obs) && p.celebrateTimer <= 0) {
      obs.passed = true;
      if (obs.type === OBS_MID && p.state === STATE_JUMP) {
        p.celebrateType = 'lookback';
        p.celebrateTimer = CELEBRATE_LOOKBACK;
        addCombo('jump');
      } else if (obs.type === OBS_LOW && p.state === STATE_SLIDE) {
        p.celebrateType = 'kick';
        p.celebrateTimer = CELEBRATE_KICK;
        addCombo('slide');
      }
    }
    if (obs.dist < COLLISION_FAR) obs.passed = true;
  }
}

function updateCoins(p) {
  for (let i = 0; i < G.coins.length; i++) {
    const coin = G.coins[i];
    if (!coin.active) continue;
    coin.dist -= G.speed;
    if (coin.dist < -400) { coin.active = false; continue; }
    if (!coin.collected && coin.dist < COLLECT_NEAR && coin.dist > COLLECT_FAR && Math.abs(coin.lane - p.lane) < COLLECT_LANE_RANGE) {
      coin.collected = true;
      coin.sparkTimer = 10;
      G.coinScore += COIN_SCORE * G.player.scoreMultiplier;
      sfxCoin();
      const s = worldToScreen(coin.dist);
      const sx = laneX(coin.lane, coin.dist);
      burstParticles(sx, s.y, 6, 20, 20, 4, [10, 25], ['#ffdd44','#ffaa00','#ffe680','#fff']);
      spawnPopup(sx, s.y - 10, '+' + COIN_SCORE * G.player.scoreMultiplier, '#ffdd44');
    }
  }
}

function updateParticles() {
  for (let i = 0; i < G.particles.length; i++) {
    const pt = G.particles[i];
    if (!pt.active) continue;
    pt.x += pt.vx;
    pt.y += pt.vy;
    pt.life--;
