function spawnTrain() {
  /* 火车在相邻轨道上运行（避开玩家当前轨道） */
  const playerLane = Math.round(G.player.lane);
  const possibleLanes = [];
  for (let l = 0; l < LANE_COUNT; l++) {
    if (l !== playerLane) possibleLanes.push(l);
  }
  if (possibleLanes.length === 0) return;
  const lane = randChoice(possibleLanes);
  const carCount = randInt(TRAIN_CAR_COUNT_MIN, TRAIN_CAR_COUNT_MAX);

  const t = poolGet(G.trains, () => ({
    active: false, dist: 0, lane: 0, carCount: 3, passed: false
  }));
  t.lane = lane;
  t.carCount = carCount;
  /* 火车从远处开始，确保所有车厢可见 */
  t.dist = G.maxDist + carCount * TRAIN_CAR_LENGTH * 0.5;
  t.passed = false;
  t.active = true;
}

function spawnCoinRow() {
  /* 单条轨道，几个金币 */
  const lane = randInt(0, 2);
  for (let d = G.maxDist - 20; d < G.maxDist + 20; d += 60) {
    const c = poolGet(G.coins, () => createCoin(0, 0));
    c.lane = lane;
    c.dist = d + Math.random() * 10;
    c.collected = false;
  }
}

function spawnPowerup() {
  const lane = randInt(0, 2);
  const type = randChoice([PUP_MAGNET, PUP_SHIELD, PUP_2X]);
  const pu = poolGet(G.powerups, () => createPowerup(0, PUP_MAGNET, 0));
  pu.lane = lane;
  pu.type = type;
  pu.dist = G.maxDist + randInt(0, 50);
  pu.collected = false;
}


function applyPowerup(p, type) {
  if (type === PUP_SHIELD) {
    p.hasShield = true;
  } else {
    p.activePowerup = type;
    p.powerupTimer = POWERUP_DURATION;
    if (type === PUP_2X) p.scoreMultiplier = 2;
  }
}
/** 清理对象池：移除距离过远且已失效的对象，防止内存无限增长 */
function cleanupPool(pool, maxSize) {
  let writeIdx = 0;
  for (let i = 0; i < pool.length; i++) {
    const obj = pool[i];
    if (obj.active || obj.dist > -600) {
      pool[writeIdx++] = obj;
    }
  }
  pool.length = writeIdx;
  // 安全阀：超过最大数量时裁剪最老的
  if (pool.length > maxSize) {
    const excess = pool.length - maxSize;
    pool.splice(0, excess);
  }
}

