function renderBackground(ctx) {
  /* 天空 */
  ctx.drawImage(G.offscreen.sky, 0, 0);
  /* 云层（独立慢速视差） */
  const cloudOffset = (G.distance * PARALLAX_CLOUD) % (G.W * 3);
  const cloudSrcW = Math.min(G.W, G.offscreen.clouds.width - cloudOffset);
  ctx.drawImage(G.offscreen.clouds, cloudOffset, 0, cloudSrcW, G.offscreen.clouds.height, 0, 0, G.W, G.offscreen.clouds.height);
  /* 远山（最慢视差） */
  const mtnOffset = (G.distance * PARALLAX_MOUNTAIN) % (G.W * 4);
  const mtnSrcW = Math.min(G.W, G.offscreen.mountains.width - mtnOffset);
  ctx.drawImage(G.offscreen.mountains, mtnOffset, 0, mtnSrcW, G.offscreen.mountains.height, 0, G.vanishY - G.offscreen.mountains.height + 60, G.W, G.offscreen.mountains.height);
  /* 城市天际线（远景） */
  const cityOffset = (G.distance * PARALLAX_FAR) % (G.W * 3);
  if (cityOffset + G.W <= G.offscreen.city.width) {
    ctx.drawImage(G.offscreen.city, cityOffset, 0, G.W, G.H*0.25, 0, G.vanishY - 30, G.W, G.H*0.25);
  } else {
    const w1 = G.offscreen.city.width - cityOffset;
    ctx.drawImage(G.offscreen.city, cityOffset, 0, w1, G.H*0.25, 0, G.vanishY - 30, w1, G.H*0.25);
    ctx.drawImage(G.offscreen.city, 0, 0, G.W - w1, G.H*0.25, w1, G.vanishY - 30, G.W - w1, G.H*0.25);
  }
  /* 近景建筑 */
  const nearOffset = (G.distance * PARALLAX_NEAR) % (G.W * 2);
  if (nearOffset + G.W <= G.offscreen.nearCity.width) {
